-- G7 event_premium_20d (Addendum 10a): the AMENDED results query, written 2026-10-30 after the builds and the diagnostics (QUERY 1 and D1 to D4) and BEFORE any premium was read.
-- It replaces QUERY 2 of g7_premium_compare_2026-10-30.sql: the premium is read on ONE ROW PER EVENT AND TICKER (the mean of the repeated rows; month and bucket agree) for the stored table (1), ARM 0 (2) and ARM 1 (3), and on the raw rows as built, repeats included, for ARM 0 (4) and ARM 1 (5).
WITH dd AS (SELECT $$1_stored$$ AS arm, event_id, ticker, MIN(m) AS m, MIN(bucket) AS bucket, AVG(scaled) AS scaled, AVG(ratio) AS ratio FROM events_ratio GROUP BY event_id, ticker UNION ALL SELECT $$2_arm0$$, event_id, ticker, MIN(m), MIN(bucket), AVG(scaled), AVG(ratio) FROM events_ratio_g7_arm0 GROUP BY event_id, ticker UNION ALL SELECT $$3_arm1$$, event_id, ticker, MIN(m), MIN(bucket), AVG(scaled), AVG(ratio) FROM events_ratio_g7_arm1 GROUP BY event_id, ticker UNION ALL SELECT $$4_arm0_raw$$, event_id, ticker, m, bucket, scaled, ratio FROM events_ratio_g7_arm0 UNION ALL SELECT $$5_arm1_raw$$, event_id, ticker, m, bucket, scaled, ratio FROM events_ratio_g7_arm1), base_m AS (SELECT m, SUM(mm_matched * mm_n) / SUM(mm_n) AS mm_month FROM mm_matched GROUP BY m), src AS (SELECT arm, event_id, m, scaled, ratio FROM dd WHERE bucket = $$a_all_other_types$$), j AS (SELECT s.arm, s.m, CASE WHEN s.m < $$2008-01-01$$ THEN $$2004-07$$ WHEN s.m < $$2013-01-01$$ THEN $$2008-12$$ WHEN s.m < $$2019-01-01$$ THEN $$2013-18$$ ELSE $$2019-26$$ END AS era, CASE WHEN s.event_id IN (SELECT id FROM new_events_20261015) THEN $$wave 1$$ WHEN s.event_id IN (SELECT id FROM new_events_wave2) THEN $$wave 2$$ ELSE $$older$$ END AS cohort, s.scaled - mm.mm_matched AS d FROM src s JOIN base_m ON base_m.m = s.m JOIN mm_matched mm ON mm.m = s.m AND mm.b = CASE WHEN s.ratio < 0.775 THEN 1 WHEN s.ratio < 0.950 THEN 2 WHEN s.ratio < 1.162 THEN 3 ELSE 4 END), g AS (SELECT arm, era, cohort, d, m FROM j UNION ALL SELECT arm, $$pooled 2004-18$$, cohort, d, m FROM j WHERE era <> $$2019-26$$), st AS (SELECT arm, era, cohort, COUNT(*) AS n, AVG(d) AS dbar, STDDEV(d) AS sd FROM g GROUP BY 1, 2, 3), cl AS (SELECT x.arm, x.era, x.cohort, SUM(x.s_m * x.s_m) AS ss FROM (SELECT g.arm, g.era, g.cohort, g.m, SUM(g.d - st.dbar) AS s_m FROM g JOIN st ON st.arm = g.arm AND st.era = g.era AND st.cohort = g.cohort GROUP BY 1, 2, 3, 4) x GROUP BY 1, 2, 3) SELECT st.arm, st.era, st.cohort, st.n, ROUND(st.dbar::numeric, 4) AS excess_matched, ROUND((st.sd / SQRT(st.n))::numeric, 4) AS se_naive, ROUND((SQRT(cl.ss) / st.n)::numeric, 4) AS se_clustered_by_month FROM st JOIN cl ON cl.arm = st.arm AND cl.era = st.era AND cl.cohort = st.cohort ORDER BY 1, 2, 3;
